use xiom.io;

type Book = { title: Str; pages: Int; }

fn read_book(b: &Book) {
  io.println(b.title.to_str() + ": " + b.pages.to_str() + " pages");
}

fn add_pages(b: &mut Book, n: Int) {
  b.pages = b.pages + n;
}

fn main() -> Int {
  var book = Book{ title: "XIOM Guide", pages: 100 };
  read_book(&book);
  add_pages(&mut book, 50);
  read_book(&book);
  return book.pages;
}
